{"outcome":"component","existing":"","reason":"","code":"QuoteWithFigures","label":"Quote and key figures","description":"A quote with the name, the role and an optional portrait of the person quoted, followed just below by a row of key figures, each a big number with a short label. Use it for a word from the director or a manager backed by the numbers of the year.","props":"[{"name":"title","type":"text","label":"Heading","help":"Optional heading above the quote.","max":120},{"name":"quote","type":"text","label":"Quote","required":true,"max":400},{"name":"author","type":"text","label":"Author","required":true,"max":80},{"name":"role","type":"text","label":"Role","max":120},{"name":"portrait","type":"image","label":"Portrait"},{"name":"figures","type":"items","label":"Key figures","min":1,"max":4,"items":[{"name":"value","type":"text","label":"Figure","required":true,"max":20},{"name":"label","type":"text","label":"What it counts","required":true,"max":120}]}]","sample":"{"title":"Le mot du directeur","quote":"Cette année, nous avons ouvert deux nouvelles boutiques sans jamais renoncer à la qualité de nos produits.","author":"Julien Moreau","role":"Directeur général","portrait":null,"figures":[{"value":"12 500","label":"commandes livrées en 2024"},{"value":"98 %","label":"de clients satisfaits"},{"value":"2","label":"nouvelles boutiques ouvertes"}]}","template":"<section class="quote-figures">{% if props.title is not empty %}<h2 class="quote-figures__title">{{ props.title }}</h2>{% endif %}<figure class="quote__figure"><blockquote class="quote__text"><p>{{ props.quote }}</p></blockquote><figcaption class="quote__caption" data-cms-sizes="3rem">{% if props.portrait %}<img class="quote__portrait" src="{{ props.portrait }}" alt="{{ props.author }}">{% endif %}<span class="quote__author">{{ props.author }}</span>{% if props.role is not empty %}<span class="quote__role">{{ props.role }}</span>{% endif %}</figcaption></figure>{% if props.figures is not empty %}<ul class="figures">{% for figure in props.figures %}<li class="figure"><span class="figure__value">{{ figure.value }}</span><span class="figure__label">{{ figure.label }}</span></li>{% endfor %}</ul>{% endif %}</section>","css":".quote-figures__title { margin: 0 0 1rem; color: var(--cms-color-text); }
.quote__figure { margin: 0; padding: 2rem 1.5rem; border-radius: 0.5rem; background: var(--cms-color-surface); }
