@media (min-width: 48rem) { .quote__figure { padding: 3rem; } .quote__text { font-size: 1.75rem; } .figures { grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); gap: 2rem; } .figure__value { font-size: 2.75rem; } }"}
